from dialogue_graph import Graph, Node, Edge

def parse_script(text: str):
    graph = Graph()
    # Split by double newline to get blocks
    blocks = re.split(r'\n\s*\n', text.strip())

    # First pass: identify all nodes to avoid missing node errors during edge addition
    node_data = {}
    for block in blocks:
        lines = [l.strip() for l in block.strip().split('\n') if l.strip()]
        if not lines:
            continue
        header_match = re.match(r'\[(\w+)\]', lines[0])
        if header_match:
            node_id = header_match.group(1)
            node_data[node_id] = lines[1:]

    # Second pass: Create nodes and edges
    for node_id, content in node_data.items():
        if not content:
            continue

        # Check if it's a choice node (starts with a digit followed by a dot)
        if re.match(r'^\d+\.', content[0]):
            graph.add_node(Node(id=node_id, type='choice'))
            for line in content:
                choice_match = re.match(r'^\d+\.\s*(.*?)\s*->\s*(\w+)', line)
                if choice_match:
                    choice_text = choice_match.group(1).strip()
                    target = choice_match.group(2).strip()
                    graph.add_edge(Edge(source=node_id, target=target, text=choice_text))
        else:
            # It's a line node
            line_match = re.match(r'^([^:]+):\s*(.*?)\s*->\s*(\w+)', content[0])
            if line_match:
                speaker = line_match.group(1).strip()
                text_content = line_match.group(2).strip()
                target = line_match.group(3).strip()
                graph.add_node(Node(id=node_id, speaker=speaker, text=text_content, type='line'))
                graph.add_edge(Edge(source=node_id, target=target))
            else:
                graph.add_node(Node(id=node_id, type='line'))

    # Ensure all referenced targets exist as nodes
    all_targets = set()
    for edge in graph.edges:
        all_targets.add(edge.target)

    for target in all_targets:
        if target not in graph.nodes:
            graph.add_node(Node(id=target, type='line', text=''))

    return graph.to_dict()

