            target = edge['to']
            text = edge.get('text', '')
            label = text.replace('"', '\\"')
            f.write(f'  "{source}" -> "{target}" [label="{label}"];\n')
        f.write("}\n")

if __name__ == "__main__":
    try:
        with open('/app/script.txt', 'r') as f:
            content = f.read()
    except FileNotFoundError:
        sys.exit(1)

